// Coordinates use original 512 px rooms, 16 px tiles, and 15.8 px player radius.
inline constexpr int roomSize = 512;
inline constexpr float playerRadius = 15.8f;
struct Point { float x, y; };
inline constexpr Point spawn{256.0f, 256.0f};
enum TileLayer : uint8_t { Tiles, BasementTiles, BasementTilesFinal, NTilesLOCK };
struct LocalPoint { int8_t x, y; };
struct TileOutline { uint8_t count; LocalPoint points[8]; };
struct Tile { int16_t x, y; uint8_t layer, outline; };
struct Room { int8_t x, y; uint16_t first, count; };
struct Shape { const char* path; uint16_t first, count; float radius; uint16_t layer, mask; uint8_t flags; };
struct Npc { const char* path; const char* dialogue; Point anchor; };
struct RoomDialogue { int8_t x, y; const char* dialogue; };
inline constexpr uint8_t staticBody = 1, initiallyDisabled = 2;

